<script setup lang="ts">
import { useDialogDraft } from '../dialog-draft'
import { computed, ref } from 'vue'
import type { UserInfo } from '../api'
import { useAdminPage } from '../admin-page'
import { getPlans, savePlan, yuan, type Plan, type PaymentChannel, type PaymentConfig, type VirtualPaymentConfig } from '../growth'
const props = defineProps<{ user: UserInfo }>()
const items = ref<Plan[]>([]), config = ref<PaymentConfig | null>(null), virtualConfig = ref<VirtualPaymentConfig | null>(null), channel = ref<PaymentChannel>('wechat'), selected = ref<Plan | null>(null), dialog = ref(false)
const name = ref(''), description = ref(''), days = ref(30), price = ref(''), active = ref(false), sort = ref(0), purchaseLimit = ref(0), virtualProductId = ref('')
const activeConfig = computed(() => channel.value === 'virtual' ? virtualConfig.value : config.value)
const priceFen = computed(() => { if (!/^\d{1,6}(\.\d{1,2})?$/.test(price.value.trim())) return 0; const [whole = '0', fraction = ''] = price.value.trim().split('.'); return Number(whole) * 100 + Number(fraction.padEnd(2, '0')) })
const page = useAdminPage(async valid => { const result = await getPlans(); if (valid()) { items.value = result.items; config.value = result.configuration; virtualConfig.value = result.virtual_configuration; channel.value = result.checkout_channel } }, () => { dialog.value = false })
const { error, notice, loading, busy } = page
function edit(item: Plan | null = null) { selected.value = item; name.value = item?.name || ''; description.value = item?.description || ''; days.value = item?.days || 30; price.value = item ? (item.price_fen / 100).toFixed(2) : ''; active.value = !!item?.is_active; sort.value = item?.sort_order || 0; purchaseLimit.value = item?.purchase_limit ?? 0; virtualProductId.value = item?.virtual_product_id || ''; error.value = ''; dialog.value = true }
function save() {
  const limit = Number(purchaseLimit.value || 0)
  if (!Number.isInteger(limit) || limit < 0 || limit > 100) { error.value = '每账号限购次数需为 0 到 100 的整数'; return }
  void page.act(async valid => { await savePlan(props.user.id, { name: name.value.trim(), description: description.value.trim(), days: Number(days.value), price_fen: priceFen.value, is_active: active.value, sort_order: Number(sort.value), purchase_limit: limit, virtual_product_id: virtualProductId.value.trim(), revision: selected.value?.revision || 0 }, selected.value?.id); if (valid()) { dialog.value = false; notice.value = '套餐已保存，已有订单仍按下单时的价格与天数结算'; await page.load() } })
}
const draft = useDialogDraft(dialog, () => [name.value, description.value, days.value, price.value, sort.value, active.value, purchaseLimit.value, virtualProductId.value], busy, '会员套餐')
</script>
<template><section class="admin-section"><div class="section-toolbar"><p class="text-sm text-muted">套餐名称、价格和会员天数由这里配置，已有订单保留原始价格与权益。订单列为累计已付款与当前待付款数量，已退款订单仍计入限购。</p><div class="actions-row"><UButton label="刷新" variant="outline" :loading="loading" @click="page.load" /><UButton label="新增套餐" icon="i-lucide-plus" @click="edit()" /></div></div><UAlert v-if="activeConfig" :title="activeConfig.ready ? '在线支付已启用' : activeConfig.enabled ? '支付已启用，但配置尚不完整' : '在线支付未启用'" :description="activeConfig.ready ? (channel === 'virtual' ? '用户在小程序内使用微信虚拟支付，微信确认后再开通会员。' : '用户在微信小程序内付款，后台收到微信确认后开通会员。') : '可以先维护套餐。完成支付配置后再启用。'" :color="activeConfig.ready ? 'success' : 'info'" class="notice" /><UAlert v-if="error" :title="error" color="error" class="notice" /><UAlert v-if="notice" :title="notice" color="success" class="notice" />
  <div class="data-scroll"><table class="data-table"><thead><tr><th>套餐</th><th>会员天数</th><th>价格</th><th>限购</th><th>已付款 / 待付</th><th v-if="channel === 'virtual'">虚拟商品 ID</th><th>状态</th><th>顺序</th><th>操作</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td class="name-cell"><strong>{{ item.name }}</strong><p class="plan-description">{{ item.description }}</p></td><td>{{ item.days }} 天</td><td>{{ yuan(item.price_fen) }}</td><td>{{ item.purchase_limit ? item.purchase_limit + ' 次' : '不限购' }}</td><td>{{ item.purchased || 0 }} / {{ item.pending || 0 }}</td><td v-if="channel === 'virtual'"><code>{{ item.virtual_product_id || '未配置' }}</code></td><td><UBadge :color="item.is_active ? 'success' : 'neutral'">{{ item.is_active ? '已上架' : '未上架' }}</UBadge></td><td>{{ item.sort_order }}</td><td><UButton label="编辑套餐" variant="soft" @click="edit(item)" /></td></tr><tr v-if="!items.length"><td :colspan="channel === 'virtual' ? 9 : 8">{{ loading ? '正在加载' : '还没有套餐，请按实际定价新增' }}</td></tr></tbody></table></div>
  <div v-if="activeConfig" class="settings-section mt-6"><h3 class="section-title">支付配置检查</h3><p v-if="activeConfig.missing.length" class="text-sm text-muted mt-3">待补齐：{{ activeConfig.missing.join('、') }}</p><dl v-if="channel === 'virtual'" class="info-list"><dt>支付渠道</dt><dd>微信小程序虚拟支付</dd><dt>OfferID</dt><dd>{{ virtualConfig?.offer_id || '未配置' }}</dd><dt>环境</dt><dd>{{ virtualConfig?.sandbox ? '沙箱' : '正式' }}</dd><dt>iOS 在线开通</dt><dd>{{ activeConfig.ios_enabled ? '已启用' : '未启用' }}</dd></dl><dl v-else class="info-list"><dt>支付回调</dt><dd>{{ config?.payment_callback || '未配置' }}</dd><dt>退款回调</dt><dd>{{ config?.refund_callback || '未配置' }}</dd><dt>iOS 在线开通</dt><dd>{{ activeConfig.ios_enabled ? '已启用' : '未启用' }}</dd></dl><p class="text-sm text-muted mt-4">商户信息、密钥文件和开关通过服务端环境配置；密钥不在后台页面录入或展示。虚拟支付需要另外在微信公众平台配置消息推送地址并发布道具。</p></div>
  <UModal v-model:open="draft.model.value" :title="selected ? '编辑会员套餐' : '新增会员套餐'" :dismissible="!busy" :close="!busy"><template #body><form id="membership-plan" class="field-stack" @submit.prevent="save"><UFormField label="套餐名称" required><UInput v-model="name" minlength="2" maxlength="80" required :disabled="busy" class="w-full" /></UFormField><UFormField label="权益说明"><UTextarea v-model="description" maxlength="1000" :disabled="busy" class="w-full" /></UFormField><div class="actions-row"><UFormField label="会员天数" required><UInput v-model="days" type="number" min="1" max="3660" step="1" required :disabled="busy" /></UFormField><UFormField label="价格（元）" required><UInput v-model="price" placeholder="由管理员填写" inputmode="decimal" required :disabled="busy" /></UFormField></div><UFormField label="展示顺序"><UInput v-model="sort" type="number" min="0" max="10000" :disabled="busy" /></UFormField><UFormField label="每账号限购次数"><UInput v-model="purchaseLimit" type="number" min="0" max="100" step="1" :disabled="busy" /><template #hint>0 表示不限购；已付款和未完成订单都计入次数，退款后仍占用额度。体验卡可设为 1。</template></UFormField><UFormField label="虚拟支付商品 ID"><UInput v-model="virtualProductId" maxlength="64" :disabled="busy" placeholder="与微信侧已发布道具一致，未启用可留空" class="w-full" /></UFormField><USwitch v-model="active" label="在小程序上架套餐" :disabled="busy" /><p class="text-sm text-muted">价格支持两位小数。付款成功后从当前有效到期日顺延；已到期用户从开通时开始计算。启用虚拟支付时，上架套餐必须填写商品 ID，且微信侧道具价格需与套餐价格一致。</p><UAlert v-if="error" :title="error" color="error" /></form></template><template #footer><UButton label="取消" color="neutral" variant="outline" :disabled="busy" @click="draft.setOpen(false)" /><UButton label="保存套餐" type="submit" form="membership-plan" :loading="busy" :disabled="busy || name.trim().length < 2 || priceFen < 1 || priceFen > 10000000 || (channel === 'virtual' && active && !virtualProductId.trim())" /></template></UModal>
</section></template>
<style scoped>.plan-description { white-space:normal;max-width:380px;margin-top:6px;color:var(--ui-text-muted);font-size:12px;line-height:1.7; }</style>
